import{j as e,a as fe,P as we,O as be,C as xe,c as ye,D as ke,R as Ie,L as $e,T as ze,q as ge}from"./ui-jX47SSyc.js";import{u as Be}from"./use-initial-loading-CmblgCBv.js";import{am as je,D as Ee,l as Ce,_ as M,N as O,B as u,ad as Le,ae as Ae,a as D,a4 as Z,Z as Oe,C as oe,c5 as ce,fK as We,fJ as Me,c3 as Ve,ar as Ue,bF as Fe,b as Ge,dr as He,ff as ve,aS as Ye,dD as Ke}from"./index-BsQu2wK9.js";import{a as c,u as Qe,f as Je,L as z}from"./vendor-DAmT3lX7.js";const Ne=[{name:"People & HR",tip:"Create one copy per person or hiring round. Assign a people partner and a team buddy after creation.",entries:[["New employee onboarding","A new teammate is joining.","A teammate has working access, clear expectations, and a first-month plan.","Confirm start date and first-month goals|Prepare equipment and approved accounts|Send the first-day agenda and team introductions|Walk through policies and role expectations|Complete a first-week check-in with the buddy|Review the first-month outcomes with the manager"],["Hiring a new role","A team needs an approved new hire.","A documented, consistent hiring decision and accepted offer.","Approve role scope, budget, and hiring owner|Write a job description and scoring rubric|Publish the role and agree sourcing channels|Screen candidates against the same criteria|Run interviews and collect independent feedback|Approve the offer and confirm the candidate response"],["Internship launch","An intern cohort is starting.","Interns begin with mentors, access, and a scoped learning project.","Define learning objectives and project boundaries|Match interns with mentors and buddies|Confirm dates, schedules, and required paperwork|Prepare tools and a sample starter assignment|Run orientation and explain feedback channels|Review week-one work and adjust the learning plan"],["Employee offboarding","A teammate is leaving or transferring out.","Work, equipment, and access are handed over with accountable owners.","Confirm the departure date and handover owner|Inventory active work and identify successors|Document critical processes and transfer files|Schedule equipment return and access removal|Complete the exit conversation and final administration|Verify handover acceptance and access closure"],["Performance review cycle","A scheduled performance cycle is due.","Evidence-based feedback and agreed development actions.","Publish the review timeline and evaluation criteria|Collect self-reflections and work examples|Request relevant peer and stakeholder feedback|Calibrate assessments with managers|Hold review conversations and document agreements|Schedule follow-ups for development actions"],["Learning workshop","A team has a shared skill gap.","Participants practice a skill and apply it to their work.","Identify the skill gap and observable learning outcome|Select a facilitator and practical examples|Prepare exercises and accessible materials|Invite participants and collect prerequisite questions|Run the workshop and capture practice feedback|Check application of the skill after two weeks"],["Employee engagement pulse","You need focused feedback on team experience.","A short survey leads to visible, owned improvements.","Choose survey themes and explain response privacy|Draft short, neutral questions|Launch the pulse and publish the closing date|Summarize themes without exposing individuals|Choose two improvements with accountable owners|Share results and schedule the next pulse"],["Internal role transfer","An employee is moving to a different team.","Both teams agree responsibilities, dates, and a smooth transition.","Confirm the new role and transfer date|Agree handover scope with both managers|Document current commitments and successors|Update approved access and reporting details|Introduce the new team and set initial objectives|Review the transition after the first month"],["Mentorship program","You want a structured mentoring round.","Matched pairs meet regularly around a measurable learning goal.","Define participant eligibility and program goals|Collect mentor skills and mentee learning interests|Match pairs and confirm availability|Share meeting guidelines and confidentiality expectations|Check midpoint participation and resolve mismatches|Collect outcomes and improve the next round"],["Team wellbeing action plan","A team identifies workload or collaboration strain.","The team agrees practical workload improvements and reviews their effect.","Gather voluntary feedback on workload and working patterns|Map recurring pressure points with the team|Choose achievable changes to workload or meeting habits|Assign owners and review dates for each change|Share support options through the people team|Review feedback and adjust the actions"]]},{name:"Software & Engineering",tip:"Use one blueprint per release or change. Add technical acceptance criteria and reviewers before starting implementation.",entries:[["Feature delivery","A validated product idea is ready to build.","A feature is tested, released, and checked against its success measure.","Agree the user problem and acceptance criteria|Review the design and technical approach|Break implementation into reviewable changes|Build the feature and review the code|Test core journeys, edge cases, and accessibility|Release gradually and review the success measure"],["Production bug fix","A reproducible defect affects users.","The defect is fixed with a regression check and verified recovery.","Capture reproduction steps and affected versions|Assess user impact and prioritize the fix|Identify the cause and add a regression check|Implement and review the smallest complete fix|Verify the affected journey in staging|Deploy and confirm the issue is resolved"],["Release readiness","A release candidate needs a go or no-go decision.","A release has an agreed scope, recovery plan, and owner sign-off.","Freeze scope and list known issues|Confirm required tests and migration checks pass|Rehearse deployment and rollback steps|Prepare release notes and support guidance|Collect release owner approval|Deploy and verify critical user journeys"],["API integration","Two systems need a reliable connection.","An integration handles authentication, failures, and operational support.","Document the API contract and data ownership|Confirm authentication and required permissions|Map fields and validate representative payloads|Implement retries, timeouts, and duplicate handling|Test success, rate limits, and failure paths|Publish operating notes and alert ownership"],["Technical debt cleanup","A recurring maintenance problem slows delivery.","A bounded refactor improves a measured engineering pain point.","Describe the maintenance cost with concrete examples|Choose a bounded scope and baseline measure|Map affected callers and regression risks|Refactor in small reviewed changes|Run relevant compatibility and behavior checks|Compare the result with the baseline and document it"],["Database migration","A schema or data change is required.","A migration is rehearsed, recoverable, and verified after rollout.","Inventory affected tables, queries, and consumers|Design a compatible transition and recovery plan|Test migration and backfill on representative data|Review locking, runtime, and deployment order|Execute the migration with monitoring|Validate record counts and application behavior"],["Service incident response","A service disruption needs coordinated response.","Service is restored and follow-up actions have owners.","Confirm impact and appoint an incident lead|Open an incident timeline and stakeholder channel|Stabilize the service with a reversible mitigation|Validate recovery with user-facing checks|Write the incident review with contributing factors|Assign prevention actions and review completion"],["Engineering sprint planning","A team is preparing its next sprint.","A capacity-aware sprint backlog supports a clear goal.","Review unfinished work and team availability|Agree one sprint goal and success criteria|Refine the highest-priority backlog items|Identify dependencies and delivery risks|Select work within available capacity|Publish the sprint plan and review checkpoints"],["Performance optimization","A slow journey has measurable user impact.","A targeted change improves latency without breaking correctness.","Choose the slow journey and target performance budget|Capture a representative baseline and traces|Identify the dominant bottleneck|Implement and review a targeted optimization|Compare performance and correctness under load|Release and monitor the improvement"],["Engineering documentation","A service lacks reliable implementation guidance.","A new contributor can understand and operate the service.","Identify readers and their key questions|Map service boundaries and dependencies|Document local setup and common development tasks|Write deployment, recovery, and troubleshooting steps|Ask a new reader to follow the instructions|Publish the guide and assign a review owner"]]},{name:"Marketing & Content",tip:"Choose one audience and one primary conversion per campaign. Replace generic task wording with your channel and launch date.",entries:[["Campaign launch","A coordinated promotion is ready to plan.","A campaign launches with consistent assets and measurable results.","Define the audience, offer, and primary conversion|Set budget, channel mix, and campaign timeline|Create the brief and approve core messaging|Produce and review channel assets|Verify tracking and launch the campaign|Review conversion results and record next actions"],["Content calendar","You need a repeatable publishing plan.","A month of audience-focused content has owners and dates.","Choose audience questions and content themes|Audit existing content for reuse and gaps|Select formats and distribution channels|Draft the calendar with authors and review dates|Review quality and schedule approved pieces|Measure engagement and update the next calendar"],["Blog article production","A useful topic deserves a published article.","A reviewed article answers a specific audience question.","Define the reader question and article objective|Gather primary references and subject expert input|Write the outline and first draft|Review accuracy, readability, and original value|Publish with metadata and accessible imagery|Distribute the article and review reader response"],["Email newsletter","Subscribers need a timely, relevant update.","A tested newsletter reaches the intended audience with clear next steps.","Choose the audience segment and newsletter objective|Select stories and write a single primary call to action|Prepare layout and accessible text alternatives|Review consent, audience exclusions, and links|Test rendering and schedule the send|Review delivery, engagement, and unsubscribe feedback"],["Social media launch","A product or announcement needs a social rollout.","A coordinated post series supports an announcement and response plan.","Choose relevant platforms and audience segments|Draft the message sequence and publishing schedule|Create channel-specific visuals and captions|Approve claims, links, and accessibility details|Publish and assign comment-response coverage|Review engagement and capture audience questions"],["Customer case study","A customer has a useful success story to share.","An approved story connects a customer problem with evidenced results.","Confirm customer participation and publication permission|Interview the customer about the original challenge|Collect evidence for outcomes and approved quotes|Draft the story and supporting visual assets|Obtain customer and internal approval|Publish and equip sales with the approved version"],["Search content improvement","An existing page underperforms for its audience.","A clearer, technically sound page better serves its search intent.","Identify the page and its intended search question|Review search performance and competing user needs|Improve coverage, structure, and internal links|Check metadata, indexing, and mobile usability|Publish changes and note the baseline date|Review search and conversion trends after indexing"],["Product announcement","A product update needs a clear public story.","Customers understand the change, benefit, and availability.","Confirm product scope, availability, and approved claims|Define the audience benefit and key message|Draft announcement copy and demonstration assets|Align support, sales, and launch stakeholders|Publish across agreed announcement channels|Collect response and correct recurring confusion"],["Brand messaging refresh","Teams describe the product inconsistently.","A shared messaging guide aligns audience, value, and proof.","Audit current messaging across customer touchpoints|Interview customers and internal stakeholders|Draft positioning, differentiators, and proof points|Test message clarity with representative readers|Approve the guide and example applications|Update priority touchpoints and brief content owners"],["Paid campaign experiment","A channel hypothesis needs a bounded test.","A controlled experiment produces a documented spending decision.","State the audience hypothesis and decision threshold|Set a fixed test budget and end date|Create comparable ad and landing-page variants|Verify attribution and conversion events|Run the test and check delivery quality|Compare results and decide to stop, revise, or expand"]]},{name:"Sales & Partnerships",tip:"Create a copy per account or opportunity. Keep evidence, next steps, and customer commitments in the project.",entries:[["Lead qualification","A new lead needs a consistent fit assessment.","A lead has an evidenced qualification decision and next step.","Review the lead source and company context|Confirm the contact role and problem to solve|Discuss fit, urgency, and decision process|Record constraints and unanswered questions|Agree a useful next step with the prospect|Update the opportunity and qualification rationale"],["Discovery call","A prospect is ready to discuss their needs.","A discovery summary connects pain points to a mutual next step.","Research the account and prepare focused questions|Confirm attendees and the call agenda|Explore current workflow, impact, and desired outcome|Clarify stakeholders and evaluation constraints|Send a concise summary for confirmation|Record follow-ups with owners and target dates"],["Tailored product demo","A qualified prospect wants to evaluate the product.","A demo answers the prospect's priority use cases and open questions.","Agree the audience and top three use cases|Prepare realistic demo data and a fallback plan|Rehearse the flow around the prospect's workflow|Deliver the demo and capture unanswered questions|Send relevant examples and confirmed answers|Agree evaluation criteria and the next meeting"],["Proposal development","A prospect needs a formal solution proposal.","A reviewed proposal clearly states scope, assumptions, and next steps.","Confirm requirements and the customer's success criteria|Define deliverables, exclusions, and assumptions|Estimate effort and review commercial inputs|Draft the proposal and implementation approach|Complete internal review and send the proposal|Schedule a walkthrough and capture requested changes"],["Account growth planning","An existing customer may benefit from broader use.","An account plan links growth opportunities to customer value.","Review account adoption, outcomes, and open issues|Map current and potential stakeholder relationships|Identify unmet needs with customer evidence|Prioritize value-led expansion opportunities|Agree an account action plan and owners|Review customer outcomes before advancing offers"],["Partner onboarding","A new partner agreement is ready for activation.","A partner can explain the offer and follow a shared engagement process.","Confirm partner scope and agreement ownership|Exchange approved contacts and operating details|Deliver product and positioning enablement|Agree lead sharing and escalation procedures|Plan the first joint activity|Review early results and address onboarding gaps"],["Sales handover to delivery","An accepted deal needs an implementation team.","Delivery accepts documented scope, commitments, and customer context.","Confirm signed scope and commercial handover requirements|Document promises, exclusions, and outstanding decisions|Introduce customer and delivery stakeholders|Transfer discovery notes and approved assets|Agree kickoff timing and acceptance measures|Obtain delivery acknowledgement of the handover"],["Renewal preparation","A customer agreement is approaching renewal.","A renewal decision follows a shared review of value and open issues.","Confirm renewal dates and decision participants|Review usage, delivered outcomes, and service issues|Ask the customer about next-period priorities|Prepare renewal scope and approved terms|Resolve questions and document the decision|Handover confirmed changes to service and billing owners"],["Win-loss review","A sales decision offers useful learning.","A recorded review identifies changes to qualification or selling practice.","Collect the opportunity timeline and decision evidence|Request optional customer feedback|Compare perceived needs with the final decision|Identify controllable strengths and gaps|Choose improvements with owners|Share the learning and review later opportunities"],["Sales territory launch","A sales team is entering a new segment or region.","A focused territory plan has target accounts, messaging, and coverage.","Define the territory boundaries and ideal customer profile|Research account fit and local buying context|Build a prioritized account list|Prepare relevant outreach and enablement material|Assign account coverage and activity checkpoints|Review response quality and refine the territory plan"]]},{name:"Customer Success & Support",tip:"Start with the customer outcome. Add the account name to the blueprint title and agree review dates with the customer.",entries:[["Customer onboarding","A new customer is ready to start using the product.","The customer completes a first valuable workflow and knows where to get help.","Confirm customer objectives and success measures|Introduce the implementation owner and key contacts|Agree setup requirements and onboarding milestones|Run training around the customer's first use case|Validate the first successful workflow together|Review adoption and hand over ongoing support"],["Support escalation","A support issue needs cross-team help.","An escalated issue has an owner, a resolution, and customer confirmation.","Summarize customer impact and reproduction evidence|Set severity and appoint a resolution owner|Route the issue with diagnostic context|Agree customer update timing|Validate the resolution with the affected customer|Document the fix and prevention follow-up"],["Quarterly customer review","A customer is due a strategic progress discussion.","The customer and team agree outcomes and next-quarter priorities.","Collect usage, outcomes, and unresolved concerns|Confirm customer participants and meeting goals|Prepare an evidence-based progress summary|Discuss priorities and changing customer needs|Agree next-quarter actions and owners|Send the shared plan and book the next checkpoint"],["Customer adoption recovery","Usage is declining or a key workflow is stalled.","A targeted plan removes adoption barriers and checks recovery.","Identify the affected users and adoption trend|Ask the customer about obstacles and changed priorities|Choose one valuable workflow to recover|Provide focused enablement or configuration help|Review usage and customer feedback after the intervention|Agree ongoing ownership or a revised success plan"],["Knowledge base article","A repeated support question needs a reusable answer.","Customers can complete a common task using verified instructions.","Collect repeated questions and the target reader context|Reproduce the workflow in a current product version|Write clear steps with expected results|Add troubleshooting and accessible screenshots|Have support verify the article|Publish and review article usefulness feedback"],["Customer feedback triage","Feedback needs a consistent path into product decisions.","Feedback is understood, grouped, and closed with a clear response.","Collect feedback with customer context and permission|Separate problems from suggested solutions|Group themes and estimate affected user impact|Review with product and support owners|Respond with the current decision or investigation plan|Track commitments and close the feedback loop"],["Service recovery plan","A service failure has damaged customer confidence.","The customer receives acknowledged ownership and verified corrective actions.","Acknowledge the issue and confirm the customer's impact|Appoint a recovery owner and communication cadence|Agree immediate corrective actions|Verify the correction with the customer|Review contributing process gaps internally|Follow up on confidence and outstanding commitments"],["Customer training series","Several user groups need practical product training.","Customer users can complete their role-specific workflows.","Identify user groups and learning goals|Design short sessions around actual customer tasks|Prepare practice data and participant materials|Run the sessions and collect questions|Share recordings or written instructions as agreed|Check workflow completion and offer targeted follow-up"],["Support queue improvement","Ticket handling is slow or inconsistent.","A queue experiment improves response quality and flow.","Baseline queue age, routing, and response quality|Identify recurring bottlenecks and misrouted tickets|Agree triage rules and escalation ownership|Pilot updated routing and response guidance|Review queue metrics and sampled conversations|Adopt effective changes and schedule another review"],["Customer champion program","Engaged customer users want to share expertise.","A voluntary champion group exchanges useful product knowledge.","Define champion participation and mutual benefits|Invite suitable users with clear expectations|Confirm communication preferences and permissions|Run a practical knowledge-sharing session|Gather suggestions and share product learning|Review participation and plan the next activity"]]},{name:"Finance & Administration",tip:"Use these as coordination checklists. Have your finance owner confirm required evidence and approval steps for your organization.",entries:[["Month-end close coordination","The finance team is preparing a period close.","Close activities have evidence, reviewed exceptions, and owner sign-off.","Confirm the close calendar and responsible owners|Collect source records and outstanding items|Complete reconciliations assigned by the finance owner|Investigate and resolve material exceptions|Obtain review of the close package|Record sign-off and carry forward open actions"],["Budget planning cycle","Teams need an agreed operating budget.","An approved budget records assumptions, owners, and review points.","Publish planning assumptions and submission dates|Collect team forecasts with supporting rationale|Compare requests against capacity and priorities|Review scenarios with finance and budget owners|Approve allocations and document tradeoffs|Schedule variance reviews and change ownership"],["Expense review","A batch of employee expenses needs processing.","Expenses have complete evidence and recorded approval decisions.","Collect claims and required supporting records|Check completeness against the expense policy|Request clarification for exceptions or missing items|Route claims to authorized approvers|Send approved claims for payment processing|Reconcile processed claims and notify claimants"],["Invoice follow-up","Customer invoices need coordinated follow-up.","Invoice questions and payment commitments have accountable next steps.","Confirm invoice accuracy and delivery records|Review due dates and existing customer queries|Contact the agreed customer finance contact|Resolve documentation or service-related disputes|Record commitments and the next follow-up date|Confirm settlement with the finance owner"],["Vendor payment preparation","Approved supplier bills are approaching payment.","A reviewed payment batch contains verified documents and approvals.","Collect approved bills and receiving evidence|Match bills with agreed purchasing records|Verify payment details through the approved process|Resolve exceptions with purchasing and finance|Route the batch for authorized payment approval|Record payment confirmation and reconcile the batch"],["Cash forecast update","A finance owner needs a current cash outlook.","A reviewed forecast records inputs, assumptions, and uncertain items.","Confirm the forecast horizon and reporting format|Collect expected receipts and planned payments|Validate opening balances with finance|Document timing assumptions and uncertain items|Review scenarios with the finance owner|Publish the approved outlook and update schedule"],["Finance audit preparation","An internal or external review is scheduled.","Requested evidence is organized with owners and tracked responses.","Confirm review scope and the requested evidence list|Assign an owner to each evidence request|Collect records in the approved access location|Check completeness and explain reconciling items|Coordinate reviewer questions and responses|Track agreed follow-up actions to closure"],["Subscription cost review","Recurring software costs need an ownership review.","Renewal decisions reflect usage, ownership, and actual business needs.","Inventory subscriptions, owners, and renewal dates|Collect usage and current spend evidence|Identify overlapping tools and unused seats|Review changes with affected teams|Approve cancellations or plan adjustments|Verify savings and update the subscription register"],["Travel administration","A work trip needs coordinated approval and logistics.","An approved trip has confirmed arrangements and complete closeout records.","Confirm purpose, travelers, and travel dates|Review the budget and required approvals|Arrange transport and accommodation under policy|Share the itinerary and practical contact details|Collect receipts and trip completion notes|Submit the expense package and close open items"],["Annual planning administration","Leadership needs a coordinated annual planning pack.","Planning submissions are complete, comparable, and ready for decisions.","Agree the planning calendar and submission format|Collect department objectives and resource requests|Check assumptions and missing supporting information|Coordinate cross-team dependency reviews|Assemble the decision pack for leadership|Record decisions and distribute approved next steps"]]},{name:"Operations & Procurement",tip:"Add a process owner and a clear completion check. Reuse successful workspace copies for the next operating cycle.",entries:[["Vendor evaluation","A team must select a new supplier.","A supplier decision is supported by comparable evidence and approvals.","Define requirements and supplier evaluation criteria|Shortlist suppliers and request comparable information|Assess capability, service, and delivery risks|Check references and relevant review requirements|Document the recommendation and obtain approval|Notify suppliers and plan the handover"],["Purchase request","A team needs to buy goods or services.","An approved purchase has a clear requirement and receiving owner.","Describe the business need and required delivery date|Confirm specifications and available budget|Collect quotations using the purchasing policy|Obtain the required purchasing approvals|Place the approved order and track delivery|Verify receipt and hand over billing evidence"],["Inventory stocktake","Physical stock needs reconciliation with records.","Stock differences are investigated and approved adjustments are recorded.","Confirm stocktake scope and counting responsibilities|Prepare count sheets and control stock movement|Count items and record location-specific evidence|Recount discrepancies independently|Review and approve inventory adjustments|Update records and assign process improvements"],["Office relocation","A team is moving to a different office.","The new location is operational and the move is accepted by teams.","Confirm space requirements, budget, and move date|Map equipment, connectivity, and access needs|Agree the move schedule with vendors and teams|Prepare the destination and test essential services|Execute the move and track exceptions|Confirm team readiness and close relocation issues"],["Standard operating procedure","A recurring process needs reliable instructions.","An approved procedure can be followed and maintained by its users.","Define process scope, owner, and expected outcome|Observe the current process and capture decision points|Write steps, inputs, exceptions, and completion checks|Trial the procedure with a representative user|Approve and publish the procedure|Schedule review and track improvement suggestions"],["Process improvement experiment","A recurring operational delay has a clear owner.","A measured experiment supports a decision to adopt or revise a process.","Define the problem and baseline process measure|Map the current flow and likely causes|Choose a small change and success threshold|Run a time-bounded pilot with process users|Compare outcomes and unintended effects|Adopt or revise the change and document learning"],["Equipment maintenance","Shared equipment is due a planned service.","Maintenance is completed and equipment is checked before return to use.","Confirm equipment inventory and service requirements|Schedule downtime with affected users|Arrange the authorized technician and parts|Record maintenance work and exceptions|Verify operational checks with the equipment owner|Update maintenance records and next service dates"],["Delivery exception resolution","An order is delayed, incomplete, or damaged.","The recipient and supplier agree a documented resolution.","Record the order, exception, and receiving evidence|Confirm the operational impact and urgency|Contact the supplier with the required resolution|Agree replacement, correction, or revised timing|Verify the resolved delivery with the recipient|Update order records and supplier feedback"],["Business continuity exercise","A team wants to rehearse a service disruption.","A realistic exercise exposes gaps and improves the continuity plan.","Choose a disruption scenario and exercise scope|Confirm participants and essential service priorities|Prepare the scenario timeline and evaluation criteria|Run the exercise and record decisions|Review recovery gaps and communication issues|Assign improvements and schedule a recheck"],["Operational handover","A service or process is changing owners.","The incoming owner accepts responsibilities, records, and open risks.","Confirm the handover scope and effective date|Inventory responsibilities, schedules, and key contacts|Document routine tasks and known exceptions|Walk through tools, records, and escalation paths|Observe the incoming owner run a representative cycle|Record acceptance and remaining follow-up actions"]]},{name:"Design & Research",tip:"Name the decision the work should inform. Include participants and accessibility needs when tailoring the checklist.",entries:[["User interview study","A product decision needs direct user understanding.","Research findings connect observed needs with a clear decision.","Define the research question and decision to inform|Recruit suitable participants with informed consent|Write a neutral discussion guide|Run interviews and store notes appropriately|Synthesize patterns and contradictory evidence|Share findings, limitations, and recommended next steps"],["Usability testing","A journey needs validation with representative users.","Observed usability issues are prioritized with supporting evidence.","Choose the journey and task success criteria|Prepare a realistic prototype or test environment|Recruit participants with relevant experience|Run neutral task-based sessions|Group issues by impact and recurring evidence|Agree fixes and plan a focused retest"],["Design sprint","A team needs to explore a difficult product problem.","A tested prototype helps the team choose its next investment.","Agree the problem, constraints, and sprint decision maker|Map the journey and gather expert input|Sketch alternative approaches independently|Choose a concept and define test assumptions|Build and test a focused prototype|Review learning and decide the next step"],["Design system component","Teams need a consistent reusable interface component.","A documented component supports required states and accessible use.","Inventory use cases and existing component variants|Define behavior, anatomy, and supported states|Design responsive and accessible variants|Review the component with design and engineering|Implement examples and verify interaction behavior|Publish usage guidance and migration notes"],["Accessibility improvement pass","A core user journey needs fewer access barriers.","Prioritized barriers are fixed and checked with appropriate methods.","Choose the journey and relevant accessibility checks|Review keyboard flow, focus, labels, and contrast|Check representative assistive technology behavior|Prioritize findings by user impact|Implement and review the improvements|Retest the journey and record remaining barriers"],["Website redesign discovery","A website redesign needs a grounded brief.","The redesign scope reflects user needs and measurable site goals.","Review current site goals and performance evidence|Interview stakeholders and representative visitors|Audit content, navigation, and key journeys|Identify constraints and content ownership|Agree redesign scope and success measures|Prepare the design brief and delivery priorities"],["Information architecture review","Users struggle to find content or features.","A tested navigation structure improves findability for key tasks.","Inventory content and current navigation labels|Identify priority user tasks and confusing categories|Draft alternative groupings and labels|Test findability with representative users|Choose the structure based on observed results|Document redirects, ownership, and rollout requirements"],["Prototype handoff","A design is ready for implementation discussion.","Engineering understands the intended behavior and unresolved decisions.","Confirm the approved journey and design scope|Annotate interaction rules and responsive behavior|Document empty, loading, error, and permission states|Review accessibility and content requirements|Walk through the prototype with engineering|Track handoff questions and verify the built result"],["Customer journey mapping","A cross-team experience needs a shared understanding.","A journey map identifies evidenced friction and accountable opportunities.","Choose the user segment and journey boundaries|Collect interviews, service records, and behavioral evidence|Map stages, touchpoints, and customer goals|Identify friction, handoffs, and evidence gaps|Prioritize opportunities with relevant teams|Assign investigation owners and review the map later"],["Product copy review","Interface wording causes confusion or inconsistency.","Clear, consistent copy supports successful user decisions.","Inventory messages in the target journey|Identify user questions and ambiguous terminology|Draft concise labels, instructions, and recovery messages|Review consistency, tone, and accessibility|Test comprehension with representative readers|Approve the copy and verify it in the interface"]]},{name:"Data & Analytics",tip:"Agree metric definitions before building. Add the data owner and a validation sample to every analytics project.",entries:[["Dashboard delivery","A team needs a trusted view of business performance.","A dashboard answers agreed questions using documented, validated metrics.","Define the audience and decisions the dashboard supports|Agree metric definitions, grain, and refresh needs|Validate data sources and access permissions|Build a focused dashboard with clear labels|Reconcile sample results with source records|Publish usage guidance and assign ongoing ownership"],["Data quality investigation","A dataset contains suspected errors or omissions.","Data issues have measured impact, root causes, and validation checks.","Describe the suspected issue and affected consumers|Profile completeness, validity, and duplicate patterns|Trace representative failures to source processes|Agree correction rules with the data owner|Fix the source or approved dataset and validate results|Add monitoring and document unresolved limitations"],["Experiment analysis","A completed experiment needs a defensible interpretation.","A documented analysis connects results, uncertainty, and a decision.","Confirm the original hypothesis and decision criteria|Check assignment, exposure, and data completeness|Calculate the agreed primary and guardrail measures|Review uncertainty and segment limitations|Discuss results with the experiment owner|Record the decision and follow-up questions"],["Data pipeline launch","A recurring dataset needs automated delivery.","A monitored pipeline delivers validated data with recovery instructions.","Agree source contracts and destination requirements|Map transformations and sensitive fields|Implement incremental loading and duplicate handling|Test validation rules and failure recovery|Deploy with freshness and failure monitoring|Document ownership and operational recovery steps"],["Metrics definition workshop","Teams use inconsistent numbers for the same concept.","A shared metric dictionary resolves definition and ownership differences.","Collect conflicting metric definitions and examples|Identify the business decisions each metric supports|Agree calculation, exclusions, grain, and timing|Validate definitions against sample records|Publish definitions with named owners|Align reports and schedule definition reviews"],["Data migration validation","Records are moving between systems.","The destination meets agreed completeness and correctness checks.","Inventory source entities and destination mappings|Define reconciliation and exception acceptance rules|Create representative test records and edge cases|Compare counts, totals, and linked relationships|Resolve exceptions and rerun affected checks|Obtain data-owner acceptance and archive evidence"],["Analytics tracking plan","A product journey needs reliable event measurement.","A reviewed event plan supports intended analysis without unnecessary data.","List the product questions and required measures|Define events, properties, and naming conventions|Review permissions and data minimization|Implement events in the target journey|Validate event order, payloads, and duplicate handling|Publish the tracking dictionary and ownership"],["Forecast model review","A planning forecast needs a quality check.","A model review explains error, assumptions, and suitable use.","Confirm the forecast purpose and decision horizon|Review training inputs and missing-data treatment|Compare with a simple baseline on held-out periods|Examine error patterns and sensitivity to assumptions|Document limitations and appropriate interpretation|Agree monitoring and a next review date"],["Self-service reporting setup","Teams repeatedly request the same data extracts.","Users can answer common questions through approved reporting resources.","Collect recurring report questions and audiences|Identify approved data sources and access boundaries|Create reusable datasets and example reports|Validate definitions and representative calculations|Train users on filters and interpretation|Collect feedback and assign dataset maintenance"],["Data access request","A team member needs access to a dataset.","Access is approved for a stated purpose and reviewed on schedule.","Record the dataset, purpose, and requested duration|Confirm the data owner and requester identity|Review the minimum necessary access|Obtain the required approval|Provision access and verify the intended workflow|Record expiry or the next access review date"]]},{name:"IT & Security",tip:"Work with your authorized IT or security owner. Record scope, approval, and verification evidence for changes.",entries:[["Access review","A system is due a permissions review.","System access reflects current responsibilities with reviewed exceptions.","Confirm systems, reviewers, and review scope|Export current accounts and permission assignments|Compare access with active roles and business need|Obtain owner decisions for exceptions|Remove or adjust approved access changes|Verify the changes and retain review evidence"],["Security patch rollout","An approved update needs coordinated deployment.","Affected systems receive a tested update with recovery coverage.","Identify affected assets and update priority|Review vendor guidance and compatibility constraints|Test the update on a representative system|Approve the rollout window and recovery steps|Deploy in stages and monitor service behavior|Verify coverage and document remaining exceptions"],["Backup restoration drill","You need evidence that a backup can be restored.","A tested restoration meets agreed data and service recovery checks.","Choose a backup and define restoration success checks|Prepare an isolated, authorized restoration environment|Confirm backup integrity and required credentials|Restore data and required service configuration|Validate data completeness and service behavior|Record recovery time, gaps, and follow-up actions"],["Security awareness session","A team needs practical security habits.","Participants recognize common risks and know the reporting route.","Choose relevant workplace security scenarios|Prepare practical examples and reporting instructions|Review the material with the security owner|Deliver the session and discuss decisions|Check understanding with scenario questions|Publish reminders and collect improvement feedback"],["New software assessment","A team wants to introduce a new tool.","A documented decision covers data, access, and operational fit.","Record the business need and proposed data use|Review authentication, permissions, and vendor controls|Assess integration and operational support needs|Confirm purchasing and relevant specialist reviews|Pilot with approved data and acceptance checks|Approve or reject adoption and record conditions"],["IT device provisioning","A new or replacement work device is needed.","An inventoried device is configured and accepted by its user.","Confirm the approved device request and user needs|Prepare the asset record and ownership details|Install approved configuration and updates|Configure required identity and security controls|Verify essential applications with the user|Record acceptance and support instructions"],["Security incident coordination","A suspected incident needs authorized investigation.","An incident has coordinated containment, recovery, and follow-up.","Record the report and notify the authorized response lead|Confirm scope and preserve relevant evidence|Coordinate containment with system owners|Track investigation findings and recovery decisions|Verify recovery and approved stakeholder communications|Document lessons and assigned corrective actions"],["Service account review","Non-human credentials need ownership and scope review.","Service accounts have current owners, justified access, and rotation plans.","Inventory service accounts and credential locations|Identify owners and dependent workloads|Review granted permissions and unused accounts|Plan approved rotation and recovery steps|Apply changes and verify dependent workloads|Record ownership and the next review date"],["IT change coordination","A shared system change may affect other teams.","A reviewed change is implemented and verified with clear communication.","Describe the change, scope, and affected services|Assess dependencies and user impact|Prepare validation and recovery instructions|Obtain approval and announce the change window|Implement the change and run agreed checks|Confirm completion and record any follow-up issues"],["Privacy request coordination","An authorized owner is handling a data-related request.","The request is routed, tracked, and closed through approved procedures.","Route the request to the designated privacy owner|Record the request scope and handling deadline set by that owner|Locate relevant systems through approved access|Coordinate identity checks and approved response actions|Obtain owner review of the prepared response|Record completion and retention instructions"]]},{name:"Events & Community",tip:"Build backwards from the event date. Create a separate copy for each event and assign a backup for live responsibilities.",entries:[["Webinar production","You want to teach or demonstrate something live online.","A tested webinar delivers useful content and a planned follow-up.","Define the audience, learning goal, and event date|Confirm speakers and the session outline|Set up registration and attendee communications|Rehearse content, captions, and technical setup|Run the webinar with a moderator and backup plan|Share agreed materials and review attendee feedback"],["In-person workshop","A group needs a practical facilitated session.","Participants complete an exercise and leave with agreed next steps.","Set the workshop objective and participant capacity|Confirm venue, accessibility needs, and materials|Prepare exercises and facilitator instructions|Send the agenda and preparation notes|Facilitate the session and capture decisions|Share outputs and check participant follow-through"],["Conference participation","A team is attending or exhibiting at a conference.","Conference activity has clear goals and accountable follow-up.","Define participation goals and approve the budget|Confirm passes, travel, and exhibit requirements|Prepare demonstrations and approved collateral|Assign staffing and meeting coverage|Capture contacts with appropriate permission|Complete follow-ups and review participation outcomes"],["Community meetup","A community wants to meet around a shared topic.","A welcoming meetup supports useful connections and learning.","Choose the topic, audience, and hosting format|Confirm hosts, speakers, and venue or platform|Publish the invitation and participation guidelines|Prepare the run sheet and accessibility arrangements|Host introductions, discussion, and closing next steps|Collect feedback and share agreed community resources"],["Hackathon coordination","Teams want a time-boxed building event.","Participants demonstrate work and record what happens after the event.","Define the challenge, eligibility, and judging criteria|Confirm mentors, tools, and event support|Publish the schedule and participant guidance|Run kickoff and team formation|Coordinate build checkpoints and final demonstrations|Record judging decisions and project continuation owners"],["Customer advisory session","You want structured input from selected customers.","Customer input informs product decisions and receives a clear follow-up.","Choose the decisions and questions for the session|Invite representative customers and confirm participation|Prepare neutral prompts and product context|Facilitate discussion and record permissioned notes|Synthesize feedback and review with decision owners|Share acknowledged themes and confirmed next steps"],["Volunteer initiative","A team is organizing a community contribution.","Volunteers have an agreed activity, support, and completion check.","Confirm the community partner and activity needs|Define volunteer roles and participation requirements|Arrange supplies, logistics, and relevant approvals|Brief volunteers on conduct and practical arrangements|Run the activity with an on-site coordinator|Thank participants and review the partner's feedback"],["Internal town hall","Leadership needs a two-way company update.","Employees receive a clear update and tracked answers to their questions.","Agree the meeting purpose and key updates|Collect employee questions through an appropriate channel|Prepare speakers, accessible slides, and timing|Test the broadcast and moderator handoffs|Run the town hall and capture unanswered questions|Publish the recap and assign follow-up answers"],["Product launch event","A product launch needs a live announcement moment.","Attendees understand the product and know how to take the next step.","Define the launch audience and event objective|Confirm demonstrations, speakers, and announcement scope|Prepare registration and approved promotional assets|Rehearse the run of show and fallback plans|Deliver the event and coordinate audience questions|Send next-step resources and review launch engagement"],["Event retrospective","A completed event needs a structured learning review.","The next event benefits from documented evidence and owned improvements.","Collect attendee feedback and operating notes|Compare attendance and outcomes with event goals|Review budget and supplier performance|Discuss what worked and what caused friction|Choose improvements for the next event|Archive reusable materials and assign follow-up owners"]]},{name:"Strategy & Project Management",tip:"Keep the scope small enough to finish. Set success criteria first, then assign owners, dates, and dependencies on the created tasks.",entries:[["Project kickoff","A cross-functional project is ready to begin.","The team agrees scope, responsibilities, and its first delivery milestone.","Write the problem statement and intended outcome|Define scope, exclusions, and acceptance criteria|Identify stakeholders and decision owners|Map milestones, dependencies, and key risks|Hold kickoff and confirm team responsibilities|Publish the plan and first progress checkpoint"],["Quarterly goal planning","A team needs focused priorities for the next quarter.","A small set of measurable goals has owners and review dates.","Review prior outcomes and current business constraints|Collect proposed priorities and supporting evidence|Choose a limited set of measurable outcomes|Map initiatives and cross-team dependencies|Assign goal owners and review dates|Publish the plan and schedule progress discussions"],["Project risk review","A project needs a shared view of uncertainty.","The most important risks have responses, triggers, and accountable owners.","Collect risks from delivery and stakeholder perspectives|Describe causes, potential impacts, and early signals|Assess likelihood and impact with the team|Choose responses and contingency actions|Assign risk owners and review triggers|Review the register at the next project checkpoint"],["Stakeholder alignment","Several teams disagree about priorities or responsibilities.","Stakeholders share a documented decision and working agreement.","Identify affected stakeholders and decision authority|Collect goals, constraints, and points of disagreement|Prepare options with implications and open questions|Facilitate the alignment discussion|Record decisions, responsibilities, and unresolved items|Confirm understanding and schedule a follow-up check"],["Project retrospective","A delivery milestone or project has finished.","The team turns evidence and experience into a few owned improvements.","Collect delivery evidence and anonymous input where appropriate|Build a shared timeline of important events|Discuss successes and contributing difficulties|Choose a small set of achievable improvements|Assign owners and target review dates|Share learning and check action completion"],["Change rollout","Teams need to adopt a new way of working.","A staged rollout supports users and checks whether adoption succeeds.","Define the change, affected groups, and adoption measure|Map workflow impacts and likely barriers|Prepare communication and practical training|Pilot the change with a representative group|Roll out with support coverage and feedback channels|Review adoption and resolve remaining obstacles"],["Business case development","An investment proposal needs a reasoned decision.","Decision makers can assess value, cost, alternatives, and uncertainty.","Describe the problem and the cost of leaving it unresolved|Gather user or operational evidence|Compare feasible options and their assumptions|Estimate costs, benefits, and delivery constraints|Review risks and define a success measure|Present the recommendation and record the decision"],["Cross-team dependency planning","Delivery depends on work owned by other teams.","Teams agree dependency commitments and escalation routes.","List deliverables and external dependencies|Confirm supplying teams and receiving owners|Agree readiness criteria and needed-by dates|Identify sequencing conflicts and capacity constraints|Publish commitments and escalation contacts|Review changes and renegotiate affected milestones"],["Project closure","A project is ready to hand over or stop.","Deliverables are accepted and ongoing responsibilities have named owners.","Check deliverables against acceptance criteria|Resolve or explicitly hand over outstanding issues|Transfer operating documentation and support ownership|Confirm final approvals and administrative closeout|Record outcomes, costs, and lessons learned|Archive project materials and release project resources"],["Leadership decision brief","A consequential decision needs a concise shared brief.","Leaders receive comparable options and record an accountable decision.","State the decision, owner, and required timing|Gather essential evidence and constraints|Describe realistic options and their tradeoffs|Consult affected stakeholders on critical assumptions|Present the recommendation and open questions|Record the decision, rationale, and follow-up owners"]]}],J=Ne.map(({name:l,tip:p})=>({name:l,tip:p})),ie=Ne.flatMap